package mlck

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"os"
)

const (
	Magic       = "MLCK"
	Version     = 1
	HeaderSize  = 16
	FooterSize  = 32
)

type Dtype uint8

const (
	Float32 Dtype = 0
	Float64 Dtype = 1
	Int32   Dtype = 2
	Int64   Dtype = 3
)

func (d Dtype) Valid() bool {
	return d == Float32 || d == Float64 || d == Int32 || d == Int64
}

func (d Dtype) Name() string {
	switch d {
	case Float32:
		return "float32"
	case Float64:
		return "float64"
	case Int32:
		return "int32"
	case Int64:
		return "int64"
	default:
		return "unknown"
	}
}

func (d Dtype) Size() int {
	switch d {
	case Float32, Int32:
		return 4
	case Float64, Int64:
		return 8
	default:
		return 0
	}
}

func DtypeName(dtype uint8) string {
	return Dtype(dtype).Name()
}

func DtypeSize(dtype uint8) int {
	return Dtype(dtype).Size()
}

func Product(shape []uint32) int64 {
	p := int64(1)
	for _, s := range shape {
		p *= int64(s)
	}
	return p
}

type Tensor struct {
	Name     string
	Dtype    uint8
	Shape    []uint32
	Data     []byte
	Checksum string
}

type TensorInfo struct {
	Name     string   `json:"name"`
	Dtype    string   `json:"dtype"`
	Shape    []uint32 `json:"shape"`
	Checksum string   `json:"checksum"`
}

func (t Tensor) Info() TensorInfo {
	return TensorInfo{
		Name:     t.Name,
		Dtype:    DtypeName(t.Dtype),
		Shape:    t.Shape,
		Checksum: t.Checksum,
	}
}

type Checkpoint struct {
	Version      uint32
	NumTensors   uint32
	Metadata     map[string]interface{}
	MetadataRaw  []byte
	Tensors      []Tensor
	FileChecksum string
	FilePath     string
}

func ParseFile(path string) (*Checkpoint, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return Parse(data, path)
}

func Parse(data []byte, path string) (*Checkpoint, error) {
	if len(data) < HeaderSize+FooterSize {
		return nil, fmt.Errorf("file too small")
	}

	if string(data[0:4]) != Magic {
		return nil, fmt.Errorf("bad magic")
	}

	version := binary.LittleEndian.Uint32(data[4:8])
	if version != Version {
		return nil, fmt.Errorf("unsupported version %d", version)
	}

	numTensors := binary.LittleEndian.Uint32(data[8:12])
	metaLen := binary.LittleEndian.Uint32(data[12:16])

	if len(data) < HeaderSize+int(metaLen)+FooterSize {
		return nil, fmt.Errorf("metadata length exceeds file size")
	}

	preceding := data[:len(data)-FooterSize]
	footer := data[len(data)-FooterSize:]
	sum := sha256.Sum256(preceding)
	fileChecksum := hex.EncodeToString(sum[:])
	if hex.EncodeToString(footer) != fileChecksum {
		return nil, fmt.Errorf("checksum mismatch")
	}

	metaRaw := data[HeaderSize : HeaderSize+int(metaLen)]
	var metadata map[string]interface{}
	if metaLen > 0 {
		if err := json.Unmarshal(metaRaw, &metadata); err != nil {
			return nil, fmt.Errorf("invalid metadata JSON: %v", err)
		}
	} else {
		metadata = map[string]interface{}{}
	}

	offset := HeaderSize + int(metaLen)
	tensors := make([]Tensor, 0, numTensors)

	for i := uint32(0); i < numTensors; i++ {
		if offset+4 > len(preceding) {
			return nil, fmt.Errorf("truncated tensor name length")
		}
		nameLen := binary.LittleEndian.Uint32(data[offset : offset+4])
		offset += 4

		if offset+int(nameLen) > len(preceding) {
			return nil, fmt.Errorf("truncated tensor name")
		}
		name := string(data[offset : offset+int(nameLen)])
		offset += int(nameLen)

		if offset+1 > len(preceding) {
			return nil, fmt.Errorf("truncated tensor dtype")
		}
		dtype := data[offset]
		offset += 1
		if !Dtype(dtype).Valid() {
			return nil, fmt.Errorf("invalid dtype %d", dtype)
		}

		if offset+4 > len(preceding) {
			return nil, fmt.Errorf("truncated tensor ndim")
		}
		ndim := binary.LittleEndian.Uint32(data[offset : offset+4])
		offset += 4

		shape := make([]uint32, ndim)
		if offset+4*int(ndim) > len(preceding) {
			return nil, fmt.Errorf("truncated tensor shape")
		}
		for j := uint32(0); j < ndim; j++ {
			shape[j] = binary.LittleEndian.Uint32(data[offset : offset+4])
			offset += 4
		}

		elemSize := DtypeSize(dtype)
		numElems := Product(shape)
		dataLen := numElems * int64(elemSize)
		if dataLen < 0 || offset+int(dataLen) > len(preceding) {
			return nil, fmt.Errorf("truncated tensor data")
		}
		tensorData := data[offset : offset+int(dataLen)]
		offset += int(dataLen)

		tSum := sha256.Sum256(tensorData)
		tensors = append(tensors, Tensor{
			Name:     name,
			Dtype:    dtype,
			Shape:    shape,
			Data:     tensorData,
			Checksum: hex.EncodeToString(tSum[:]),
		})
	}

	if offset != len(preceding) {
		return nil, fmt.Errorf("extra data after tensors")
	}

	return &Checkpoint{
		Version:      version,
		NumTensors:   numTensors,
		Metadata:     metadata,
		MetadataRaw:  metaRaw,
		Tensors:      tensors,
		FileChecksum: fileChecksum,
		FilePath:     path,
	}, nil
}

func Build(metadata map[string]interface{}, tensors []Tensor) ([]byte, error) {
	metaRaw, err := json.Marshal(metadata)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal metadata: %v", err)
	}

	var buf bytes.Buffer
	header := make([]byte, HeaderSize)
	copy(header[0:4], Magic)
	binary.LittleEndian.PutUint32(header[4:8], Version)
	binary.LittleEndian.PutUint32(header[8:12], uint32(len(tensors)))
	binary.LittleEndian.PutUint32(header[12:16], uint32(len(metaRaw)))
	buf.Write(header)
	buf.Write(metaRaw)

	for _, t := range tensors {
		nameBytes := []byte(t.Name)
		if err := binary.Write(&buf, binary.LittleEndian, uint32(len(nameBytes))); err != nil {
			return nil, err
		}
		buf.Write(nameBytes)
		buf.WriteByte(t.Dtype)
		if err := binary.Write(&buf, binary.LittleEndian, uint32(len(t.Shape))); err != nil {
			return nil, err
		}
		for _, s := range t.Shape {
			if err := binary.Write(&buf, binary.LittleEndian, s); err != nil {
				return nil, err
			}
		}
		expected := Product(t.Shape) * int64(DtypeSize(t.Dtype))
		if int64(len(t.Data)) != expected {
			return nil, fmt.Errorf("tensor %s data length %d does not match shape %v and dtype %s", t.Name, len(t.Data), t.Shape, DtypeName(t.Dtype))
		}
		buf.Write(t.Data)
	}

	sum := sha256.Sum256(buf.Bytes())
	buf.Write(sum[:])
	return buf.Bytes(), nil
}

func WriteFile(path string, metadata map[string]interface{}, tensors []Tensor) error {
	data, err := Build(metadata, tensors)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func (t Tensor) Float64Values() ([]float64, error) {
	size := DtypeSize(t.Dtype)
	if size == 0 {
		return nil, fmt.Errorf("invalid dtype %d", t.Dtype)
	}
	n := len(t.Data) / size
	if len(t.Data)%size != 0 {
		return nil, fmt.Errorf("tensor %s data length not multiple of dtype size", t.Name)
	}
	vals := make([]float64, n)
	for i := 0; i < n; i++ {
		start := i * size
		switch Dtype(t.Dtype) {
		case Float32:
			bits := binary.LittleEndian.Uint32(t.Data[start : start+4])
			vals[i] = float64(math.Float32frombits(bits))
		case Float64:
			bits := binary.LittleEndian.Uint64(t.Data[start : start+8])
			vals[i] = math.Float64frombits(bits)
		case Int32:
			vals[i] = float64(int32(binary.LittleEndian.Uint32(t.Data[start : start+4])))
		case Int64:
			vals[i] = float64(int64(binary.LittleEndian.Uint64(t.Data[start : start+8])))
		default:
			return nil, fmt.Errorf("invalid dtype %d", t.Dtype)
		}
	}
	return vals, nil
}

func EncodeFloat64Values(vals []float64, dtype uint8) ([]byte, error) {
	var buf bytes.Buffer
	switch Dtype(dtype) {
	case Float32:
		for _, v := range vals {
			if err := binary.Write(&buf, binary.LittleEndian, math.Float32bits(float32(v))); err != nil {
				return nil, err
			}
		}
	case Float64:
		for _, v := range vals {
			if err := binary.Write(&buf, binary.LittleEndian, math.Float64bits(v)); err != nil {
				return nil, err
			}
		}
	case Int32:
		for _, v := range vals {
			if err := binary.Write(&buf, binary.LittleEndian, int32(math.Round(v))); err != nil {
				return nil, err
			}
		}
	case Int64:
		for _, v := range vals {
			if err := binary.Write(&buf, binary.LittleEndian, int64(math.Round(v))); err != nil {
				return nil, err
			}
		}
	default:
		return nil, fmt.Errorf("invalid dtype %d", dtype)
	}
	return buf.Bytes(), nil
}

func PromoteDtype(a, b uint8) (uint8, error) {
	if a == b {
		return a, nil
	}
	rank := func(d uint8) int {
		switch Dtype(d) {
		case Int32:
			return 0
		case Int64:
			return 1
		case Float32:
			return 2
		case Float64:
			return 3
		default:
			return -1
		}
	}
	ra := rank(a)
	rb := rank(b)
	if ra < 0 || rb < 0 {
		return 0, fmt.Errorf("invalid dtype promotion %d and %d", a, b)
	}
	if ra >= rb {
		return a, nil
	}
	return b, nil
}
