package manifest

import (
    "fmt"
    "os"
    "regexp"
    "strconv"
    "strings"
    "time"
)

type Result struct {
    Valid bool `json:"valid"`
    Warnings []string `json:"warnings,omitempty"`
    Errors []string `json:"errors,omitempty"`
}

func Validate(path string) *Result {
    data, err := os.ReadFile(path)
    if err != nil {
        return &Result{
            Valid: false,
            Errors: []string{fmt.Sprintf("failed to read manifest: %v", err)},
        }
    }

    root, err := parseTOML(string(data))
    if err != nil {
        return &Result{
            Valid: false,
            Errors: []string{fmt.Sprintf("failed to parse manifest: %v", err)},
        }
    }

    result := &Result{
        Valid: true,
        Warnings: []string{},
        Errors: []string{},
    }

    experiment := getTable(root, "experiment")
    environment := getTable(root, "environment")
    dependencies := root["dependencies"]
    outputs := getTable(root, "outputs")

    if experiment == nil {
        result.Errors = append(result.Errors, "missing required field: experiment.name")
        result.Errors = append(result.Errors, "missing required field: experiment.timestamp")
    } else {
        name, ok := experiment["name"].(string)
        if !ok || name == "" {
            result.Errors = append(result.Errors, "missing required field: experiment.name")
        }
        timestamp, ok := experiment["timestamp"].(string)
        if !ok || timestamp == "" {
            result.Errors = append(result.Errors, "missing required field: experiment.timestamp")
        } else if _, err := time.Parse(time.RFC3339, timestamp); err != nil {
            result.Errors = append(result.Errors, "invalid timestamp format")
        }
    }

    if environment == nil {
        result.Errors = append(result.Errors, "missing required field: environment.python_version")
        result.Errors = append(result.Errors, "missing required field: environment.seed")
        result.Errors = append(result.Errors, "missing required field: environment.deterministic")
        result.Errors = append(result.Errors, "optional field 'environment.gpu_id' missing")
        result.Errors = append(result.Errors, "optional field 'environment.cuda_version' missing")
    } else {
        pythonVersion, ok := environment["python_version"].(string)
        if !ok || pythonVersion == "" {
            result.Errors = append(result.Errors, "missing required field: environment.python_version")
        } else if !pythonVersionRegex.MatchString(pythonVersion) {
            result.Errors = append(result.Errors, "invalid python_version format")
        }

        seed, ok := environment["seed"]
        if !ok {
            result.Errors = append(result.Errors, "missing required field: environment.seed")
        } else if !isNonNegativeInt(seed) {
            result.Errors = append(result.Errors, "invalid environment.seed")
        }

        deterministic, ok := environment["deterministic"].(bool)
        if !ok {
            result.Errors = append(result.Errors, "missing required field: environment.deterministic")
        } else if !deterministic {
            // deterministic is required boolean; false is valid.
            _ = deterministic
        }

        if _, ok := environment["gpu_id"].(string); !ok {
            result.Warnings = append(result.Warnings, "optional field 'environment.gpu_id' missing")
        }
        if _, ok := environment["cuda_version"].(string); !ok {
            result.Warnings = append(result.Warnings, "optional field 'environment.cuda_version' missing")
        }
    }

    deps, ok := dependencies.([]map[string]interface{})
    if !ok {
        result.Errors = append(result.Errors, "missing required field: dependencies")
    } else {
        for i, dep := range deps {
            name, nameOk := dep["name"].(string)
            version, versionOk := dep["version"].(string)
            if !nameOk || name == "" {
                result.Errors = append(result.Errors, fmt.Sprintf("invalid dependency at index %d: missing name", i))
            }
            if !versionOk || version == "" {
                result.Errors = append(result.Errors, fmt.Sprintf("invalid dependency at index %d: missing version", i))
            }
        }
    }

    if outputs == nil {
        result.Errors = append(result.Errors, "missing required field: outputs.checkpoint_path")
        result.Errors = append(result.Errors, "missing required field: outputs.metrics")
    } else {
        checkpointPath, ok := outputs["checkpoint_path"].(string)
        if !ok || checkpointPath == "" {
            result.Errors = append(result.Errors, "missing required field: outputs.checkpoint_path")
        }
        metrics := getTable(outputs, "metrics")
        if metrics == nil {
            result.Errors = append(result.Errors, "missing required field: outputs.metrics")
        } else if !hasNumericField(metrics) {
            result.Errors = append(result.Errors, "outputs.metrics must contain at least one numeric field")
        }
    }

    git := getTable(root, "git")
    if git == nil {
        result.Warnings = append(result.Warnings, "optional field 'git.commit' missing")
        result.Warnings = append(result.Warnings, "optional field 'git.branch' missing")
    } else {
        if _, ok := git["commit"].(string); !ok {
            result.Warnings = append(result.Warnings, "optional field 'git.commit' missing")
        }
        if _, ok := git["branch"].(string); !ok {
            result.Warnings = append(result.Warnings, "optional field 'git.branch' missing")
        }
    }

    if len(result.Errors) > 0 {
        result.Valid = false
        result.Warnings = nil
    }
    if result.Valid && len(result.Warnings) == 0 {
        result.Warnings = []string{}
    }

    return result
}

var pythonVersionRegex = regexp.MustCompile(`^\d+\.\d+\.\d+$`)

func getTable(root map[string]interface{}, key string) map[string]interface{} {
    v, ok := root[key]
    if !ok {
        return nil
    }
    m, ok := v.(map[string]interface{})
    if !ok {
        return nil
    }
    return m
}

func isNonNegativeInt(v interface{}) bool {
    switch x := v.(type) {
    case int:
        return x >= 0
    case int64:
        return x >= 0
    case float64:
        return x == float64(int64(x)) && x >= 0
    default:
        return false
    }
}

func hasNumericField(m map[string]interface{}) bool {
    for _, v := range m {
        switch v.(type) {
        case int, int64, float64:
            return true
        }
    }
    return false
}

func parseTOML(data string) (map[string]interface{}, error) {
    root := map[string]interface{}{}
    var current map[string]interface{} = root
    var currentArray []map[string]interface{}
    var currentArrayKey string

    lines := strings.Split(data, "\n")
    for lineNum, raw := range lines {
        line := strings.TrimSpace(raw)
        if line == "" || strings.HasPrefix(line, "#") {
            continue
        }

        if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]" {
            key := strings.TrimSpace(line[2 : len(line)-2])
            parts := strings.Split(key, ".")
            parent := root
            for i := 0; i < len(parts)-1; i++ {
                p := strings.TrimSpace(parts[i])
                next, ok := parent[p]
                if !ok {
                    next = map[string]interface{}{}
                    parent[p] = next
                }
                parent, ok = next.(map[string]interface{})
                if !ok {
                    return nil, fmt.Errorf("line %d: invalid array table path", lineNum+1)
                }
            }
            last := strings.TrimSpace(parts[len(parts)-1])
            arr, ok := parent[last].([]map[string]interface{})
            if !ok {
                arr = []map[string]interface{}{}
            }
            item := map[string]interface{}{}
            arr = append(arr, item)
            parent[last] = arr
            current = item
            currentArray = arr
            currentArrayKey = last
            continue
        }

        if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
            key := strings.TrimSpace(line[1 : len(line)-1])
            parts := strings.Split(key, ".")
            parent := root
            for i := 0; i < len(parts)-1; i++ {
                p := strings.TrimSpace(parts[i])
                next, ok := parent[p]
                if !ok {
                    next = map[string]interface{}{}
                    parent[p] = next
                }
                parent, ok = next.(map[string]interface{})
                if !ok {
                    return nil, fmt.Errorf("line %d: invalid table path", lineNum+1)
                }
            }
            last := strings.TrimSpace(parts[len(parts)-1])
            tbl, ok := parent[last].(map[string]interface{})
            if !ok {
                tbl = map[string]interface{}{}
                parent[last] = tbl
            }
            current = tbl
            currentArray = nil
            currentArrayKey = ""
            continue
        }

        eq := strings.Index(line, "=")
        if eq < 0 {
            return nil, fmt.Errorf("line %d: expected key = value", lineNum+1)
        }
        key := strings.TrimSpace(line[:eq])
        valueStr := strings.TrimSpace(line[eq+1:])
        value, err := parseTOMLValue(valueStr)
        if err != nil {
            return nil, fmt.Errorf("line %d: %v", lineNum+1, err)
        }
        if currentArray != nil && currentArrayKey != "" {
            current[key] = value
        }
        current[key] = value
    }

    return root, nil
}

func parseTOMLValue(s string) (interface{}, error) {
    if s == "true" {
        return true, nil
    }
    if s == "false" {
        return false, nil
    }
    if len(s) >= 2 && (s[0] == '"' && s[len(s)-1] == '"' || s[0] == '\'' && s[len(s)-1] == '\'') {
        return s[1 : len(s)-1], nil
    }
    if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
        inner := strings.TrimSpace(s[1 : len(s)-1])
        if inner == "" {
            return []interface{}{}, nil
        }
        parts := splitArrayElements(inner)
        arr := make([]interface{}, 0, len(parts))
        for _, p := range parts {
            v, err := parseTOMLValue(strings.TrimSpace(p))
            if err != nil {
                return nil, err
            }
            arr = append(arr, v)
        }
        return arr, nil
    }
    if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
        inner := strings.TrimSpace(s[1 : len(s)-1])
        m := map[string]interface{}{}
        if inner == "" {
            return m, nil
        }
        parts := splitArrayElements(inner)
        for _, p := range parts {
            kv := strings.SplitN(p, "=", 2)
            if len(kv) != 2 {
                return nil, fmt.Errorf("invalid inline table entry: %s", p)
            }
            k := strings.TrimSpace(kv[0])
            v, err := parseTOMLValue(strings.TrimSpace(kv[1]))
            if err != nil {
                return nil, err
            }
            m[k] = v
        }
        return m, nil
    }
    if i, err := strconv.ParseInt(s, 10, 64); err == nil {
        return i, nil
    }
    if f, err := strconv.ParseFloat(s, 64); err == nil {
        return f, nil
    }
    return nil, fmt.Errorf("invalid value: %s", s)
}

func splitArrayElements(s string) []string {
    var parts []string
    depth := 0
    quote := byte(0)
    start := 0
    for i := 0; i < len(s); i++ {
        c := s[i]
        if quote != 0 {
            if c == quote {
                quote = 0
            }
            continue
        }
        if c == '"' || c == '\'' {
            quote = c
            continue
        }
        if c == '[' || c == '{' {
            depth++
        } else if c == ']' || c == '}' {
            depth--
        } else if c == ',' && depth == 0 {
            parts = append(parts, s[start:i])
            start = i + 1
        }
    }
    parts = append(parts, s[start:])
    return parts
}
