func detectCycle(exps []Experiment) []string {
    adj := make(map[string][]string)
    for _, e := range exps {
        for _, p := range e.Parents {
            adj[p] = append(adj[p], e.ID)
        }
    }

    state := make(map[string]int)
    var stack []string
    var cycle []string

    var dfs func(id string) bool
    dfs = func(id string) bool {
        state[id] = 1
        stack = append(stack, id)
        for _, child := range adj[id] {
            if state[child] == 1 {
                idx := -1
                for i := len(stack) - 1; i >= 0; i-- {
                    if stack[i] == child {
                        idx = i
                        break
                    }
                }
                if idx >= 0 {
                    cycle = append([]string{}, stack[idx:]...)
                    return true
                }
            }
            if state[child] == 0 {
                if dfs(child) {
                    return true
                }
            }
        }
        stack = stack[:len(stack)-1]
        state[id] = 2
        return false
    }

    for _, e := range exps {
        if state[e.ID] == 0 {
            if dfs(e.ID) {
                return cycle
            }
        }
    }
    return nil
}
