package merge

import (
    "fmt"
    "path/filepath"

    "repro-verify/internal/mlck"
)

type TensorSource struct {
    Name string `json:"name"`
    Sources []string `json:"sources"`
    Resolution string `json:"resolution"`
}

type Result struct {
    OutputFile string `json:"output_file"`
    NumInputFiles int `json:"num_input_files"`
    TotalTensors int `json:"total_tensors"`
    ConflictsResolved int `json:"conflicts_resolved"`
    ConflictStrategy string `json:"conflict_strategy"`
    TensorSources []TensorSource `json:"tensor_sources"`
}

func Merge(output string, files []string, strategy string) (*Result, error) {
    if len(files) < 2 {
        return nil, fmt.Errorf("at least 2 input files required")
    }
    if strategy != "first" && strategy != "last" && strategy != "average" {
        return nil, fmt.Errorf("invalid conflict strategy %q", strategy)
    }

    cps := make([]*mlck.Checkpoint, len(files))
    for i, f := range files {
        cp, err := mlck.ParseFile(f)
        if err != nil {
            return nil, fmt.Errorf("file %s: %v", f, err)
        }
        cps[i] = cp
    }

    metadata := map[string]interface{}{}
    for _, cp := range cps {
        for k, v := range cp.Metadata {
            metadata[k] = v
        }
    }

    type occurrence struct {
        fileIdx int
        tensor mlck.Tensor
    }

    var order []string
    occurrences := map[string][]occurrence{}
    for i, cp := range cps {
        for _, t := range cp.Tensors {
            if _, ok := occurrences[t.Name]; !ok {
                order = append(order, t.Name)
            }
            occurrences[t.Name] = append(occurrences[t.Name], occurrence{i, t})
        }
    }

    outTensors := make([]mlck.Tensor, 0, len(order))
    tensorSources := make([]TensorSource, 0, len(order))
    conflicts := 0

    for _, name := range order {
        occs := occurrences[name]
        sources := make([]string, len(occs))
        for i, occ := range occs {
            sources[i] = filepath.Base(files[occ.fileIdx])
        }

        resolution := "unique"
        var tensor mlck.Tensor
        if len(occs) > 1 {
            conflicts++
            switch strategy {
            case "first":
                tensor = occs[0].tensor
                resolution = "first"
            case "last":
                tensor = occs[len(occs)-1].tensor
                resolution = "last"
            case "average":
                shape := occs[0].tensor.Shape
                for _, occ := range occs[1:] {
                    if !shapesEqual(shape, occ.tensor.Shape) {
                        return nil, fmt.Errorf("tensor %s shape mismatch for average", name)
                    }
                }
                dtype := occs[0].tensor.Dtype
                for _, occ := range occs[1:] {
                    promoted, err := mlck.PromoteDtype(dtype, occ.tensor.Dtype)
                    if err != nil {
                        return nil, err
                    }
                    dtype = promoted
                }
                n := int(mlck.Product(shape))
                sums := make([]float64, n)
                for _, occ := range occs {
                    vals, err := occ.tensor.Float64Values()
                    if err != nil {
                        return nil, err
                    }
                    if len(vals) != n {
                        return nil, fmt.Errorf("tensor %s value count mismatch", name)
                    }
                    for i := range sums {
                        sums[i] += vals[i]
                    }
                }
                avg := make([]float64, n)
                for i := range sums {
                    avg[i] = sums[i] / float64(len(occs))
                }
                data, err := mlck.EncodeFloat64Values(avg, dtype)
                if err != nil {
                    return nil, err
                }
                tensor = mlck.Tensor{
                    Name: name,
                    Dtype: dtype,
                    Shape: shape,
                    Data: data,
                }
                resolution = "averaged"
            }
        } else {
            tensor = occs[0].tensor
        }

        outTensors = append(outTensors, tensor)
        tensorSources = append(tensorSources, TensorSource{
            Name: name,
            Sources: sources,
            Resolution: resolution,
        })
    }

    if err := mlck.WriteFile(output, metadata, outTensors); err != nil {
        return nil, err
    }

    return &Result{
        OutputFile: output,
        NumInputFiles: len(files),
        TotalTensors: len(outTensors),
        ConflictsResolved: conflicts,
        ConflictStrategy: strategy,
        TensorSources: tensorSources,
    }, nil
}

func shapesEqual(a, b []uint32) bool {
    if len(a) != len(b) {
        return false
    }
    for i := range a {
        if a[i] != b[i] {
            return false
        }
    }
    return true
}
