package drift

import (
    "fmt"
    "math"

    "repro-verify/internal/mlck"
)

type TensorResult struct {
    Name string `json:"name"`
    StepChanges []float64 `json:"step_changes"`
    MeanChange float64 `json:"mean_change"`
    MaxChange float64 `json:"max_change"`
    Convergence string `json:"convergence"`
    StabilityScore float64 `json:"stability_score"`
}

type Result struct {
    NumSnapshots int `json:"num_snapshots"`
    NumAnalyzedTensors int `json:"num_analyzed_tensors"`
    SkippedTensors []string `json:"skipped_tensors"`
    Tensors []TensorResult `json:"tensors"`
    OverallConvergence string `json:"overall_convergence"`
}

func Analyze(files []string) (*Result, error) {
    if len(files) < 2 {
        return nil, fmt.Errorf("at least 2 input files required")
    }

    cps := make([]*mlck.Checkpoint, len(files))
    for i, f := range files {
        cp, err := mlck.ParseFile(f)
        if err != nil {
            return nil, fmt.Errorf("file %s: %v", f, err)
        }
        cps[i] = cp
    }

    var allNames []string
    seen := map[string]bool{}
    for _, cp := range cps {
        for _, t := range cp.Tensors {
            if !seen[t.Name] {
                seen[t.Name] = true
                allNames = append(allNames, t.Name)
            }
        }
    }

    skipped := []string{}
    tensors := []TensorResult{}
    converging := 0
    diverging := 0

    for _, name := range allNames {
        ok := true
        var shape []uint32
        for _, cp := range cps {
            t, exists := tensorByName(cp, name)
            if !exists {
                ok = false
                break
            }
            if shape == nil {
                shape = t.Shape
            } else if !shapesEqual(shape, t.Shape) {
                ok = false
                break
            }
        }
        if !ok {
            skipped = append(skipped, name)
            continue
        }

        steps := make([]float64, len(cps)-1)
        for i := 0; i < len(cps)-1; i++ {
            t1 := tensorByName(cps[i], name)
            t2 := tensorByName(cps[i+1], name)
            v1, err := t1.Float64Values()
            if err != nil {
                return nil, err
            }
            v2, err := t2.Float64Values()
            if err != nil {
                return nil, err
            }
            n := len(v1)
            if n == 0 {
                steps[i] = 0
                continue
            }
            var sum float64
            for j := 0; j < n; j++ {
                sum += math.Abs(v1[j] - v2[j])
            }
            steps[i] = sum / float64(n)
        }

        mean := meanFloat64(steps)
        max := maxFloat64(steps)
        convergence := classifyConvergence(steps)
        stability := 1.0
        if steps[0] != 0 {
            stability = 1.0 - steps[len(steps)-1]/steps[0]
            if stability < 0 {
                stability = 0
            } else if stability > 1 {
                stability = 1
            }
        }

        tensors = append(tensors, TensorResult{
            Name: name,
            StepChanges: steps,
            MeanChange: mean,
            MaxChange: max,
            Convergence: convergence,
            StabilityScore: stability,
        })

        if convergence == "converging" {
            converging++
        } else if convergence == "diverging" {
            diverging++
        }
    }

    overall := "mixed"
    if converging > len(tensors)/2 {
        overall = "converging"
    } else if diverging > len(tensors)/2 {
        overall = "diverging"
    }

    return &Result{
        NumSnapshots: len(files),
        NumAnalyzedTensors: len(tensors),
        SkippedTensors: skipped,
        Tensors: tensors,
        OverallConvergence: overall,
    }, nil
}

func tensorByName(cp *mlck.Checkpoint, name string) (mlck.Tensor, bool) {
    for _, t := range cp.Tensors {
        if t.Name == name {
            return t, true
        }
    }
    return mlck.Tensor{}, false
}

func shapesEqual(a, b []uint32) bool {
    if len(a) != len(b) {
        return false
    }
    for i := range a {
        if a[i] != b[i] {
            return false
        }
    }
    return true
}

func meanFloat64(xs []float64) float64 {
    if len(xs) == 0 {
        return 0
    }
    var sum float64
    for _, x := range xs {
        sum += x
    }
    return sum / float64(len(xs))
}

func maxFloat64(xs []float64) float64 {
    if len(xs) == 0 {
        return 0
    }
    m := xs[0]
    for _, x := range xs[1:] {
        if x > m {
            m = x
        }
    }
    return m
}

func classifyConvergence(steps []float64) string {
    if len(steps) <= 1 {
        return "converging"
    }
    decreasing := true
    increasing := true
    for i := 1; i < len(steps); i++ {
        if steps[i] >= steps[i-1] {
            decreasing = false
        }
        if steps[i] <= steps[i-1] {
            increasing = false
        }
    }
    if decreasing {
        return "converging"
    }
    if increasing {
        return "diverging"
    }
    return "oscillating"
}
