package report

import (
    "fmt"
    "strings"
    "time"

    "repro-verify/internal/compare"
    "repro-verify/internal/lineage"
    "repro-verify/internal/manifest"
    "repro-verify/internal/mlck"
)

type ManifestPart struct {
    Valid bool `json:"valid"`
    Warnings []string `json:"warnings,omitempty"`
    Errors []string `json:"errors,omitempty"`
}

type CheckpointPart struct {
    Valid bool `json:"valid"`
    NumTensors int `json:"num_tensors,omitempty"`
    FileChecksum string `json:"file_checksum,omitempty"`
    Error string `json:"error,omitempty"`
}

type ComparisonPart struct {
    Match bool `json:"match"`
    Summary string `json:"summary,omitempty"`
    Error string `json:"error,omitempty"`
}

type LineagePart struct {
    Valid bool `json:"valid"`
    Depth int `json:"depth,omitempty"`
    Error string `json:"error,omitempty"`
}

type Report struct {
    ReportVersion string `json:"report_version"`
    Timestamp string `json:"timestamp"`
    Manifest ManifestPart `json:"manifest"`
    Checkpoint CheckpointPart `json:"checkpoint,omitempty"`
    Comparison ComparisonPart `json:"comparison,omitempty"`
    Lineage LineagePart `json:"lineage,omitempty"`
    OverallReproducible bool `json:"overall_reproducible"`
    Issues []string `json:"issues"`
}

func Generate(manifestPath, checkpointPath, comparePath, lineagePath string) (*Report, int) {
    issues := []string{}
    rep := &Report{
        ReportVersion: "1.0",
        Timestamp: time.Now().Format(time.RFC3339),
        Issues: issues,
    }

    man := manifest.Validate(manifestPath)
    rep.Manifest = ManifestPart{
        Valid: man.Valid,
        Warnings: man.Warnings,
        Errors: man.Errors,
    }
    if !man.Valid {
        issues = append(issues, fmt.Sprintf("Manifest validation failed: %s", strings.Join(man.Errors, "; ")))
    }

    checkpointValid := true
    if checkpointPath != "" {
        cp, err := mlck.ParseFile(checkpointPath)
        if err != nil {
            checkpointValid = false
            rep.Checkpoint = CheckpointPart{
                Valid: false,
                Error: err.Error(),
            }
            issues = append(issues, fmt.Sprintf("Checkpoint verification failed: %v", err))
        } else {
            rep.Checkpoint = CheckpointPart{
                Valid: true,
                NumTensors: len(cp.Tensors),
                FileChecksum: cp.FileChecksum,
            }
        }
    }

    comparisonMatch := true
    if checkpointPath != "" && comparePath != "" {
        c1, err := mlck.ParseFile(checkpointPath)
        if err != nil {
            comparisonMatch = false
            rep.Comparison = ComparisonPart{
                Match: false,
                Error: fmt.Sprintf("checkpoint parse failed: %v", err),
            }
            issues = append(issues, fmt.Sprintf("Comparison failed: %v", err))
        } else {
            c2, err := mlck.ParseFile(comparePath)
            if err != nil {
                comparisonMatch = false
                rep.Comparison = ComparisonPart{
                    Match: false,
                    Error: fmt.Sprintf("compare checkpoint parse failed: %v", err),
                }
                issues = append(issues, fmt.Sprintf("Comparison failed: %v", err))
            } else {
                res, err := compare.Compare(c1, c2, "strict", 1e-7, 1e-5)
                if err != nil {
                    comparisonMatch = false
                    rep.Comparison = ComparisonPart{
                        Match: false,
                        Error: err.Error(),
                    }
                    issues = append(issues, fmt.Sprintf("Comparison failed: %v", err))
                } else {
                    differ := 0
                    total := len(res.TensorResults)
                    for _, tr := range res.TensorResults {
                        if !tr.Match {
                            differ++
                        }
                    }
                    rep.Comparison = ComparisonPart{
                        Match: res.Match,
                        Summary: fmt.Sprintf("%d/%d tensors differ", differ, total),
                    }
                    if !res.Match {
                        comparisonMatch = false
                        if differ > 0 {
                            issues = append(issues, fmt.Sprintf("Tensor comparison failed: %d tensors differ beyond tolerance", differ))
                        } else {
                            issues = append(issues, "Tensor comparison failed: missing tensors or shape mismatch")
                        }
                    }
                }
            }
        }
    }

    lineageValid := true
    if lineagePath != "" {
        lin := lineage.Audit(lineagePath)
        if lin.Valid {
            rep.Lineage = LineagePart{
                Valid: true,
                Depth: lin.MaxDepth,
            }
        } else {
            lineageValid = false
            rep.Lineage = LineagePart{
                Valid: false,
                Error: strings.Join(lin.Errors, "; "),
            }
            issues = append(issues, fmt.Sprintf("Lineage audit failed: %s", strings.Join(lin.Errors, "; ")))
        }
    }

    overall := man.Valid && checkpointValid && comparisonMatch && lineageValid
    rep.OverallReproducible = overall
    rep.Issues = issues

    if overall {
        return rep, 0
    }
    return rep, 1
}
