            "mode": *mode,
            "atol": *atol,
            "rtol": *rtol,
            "tensor_results": []interface{}{},
            "missing_in_file1": []string{},
            "missing_in_file2": []string{},
            "error": fmt.Sprintf("file1: %v", err),
        })
        return 1
    }

    c2, err := mlck.ParseFile(pos[1])
    if err != nil {
        outputJSON(map[string]interface{}{
            "match": false,
            "mode": *mode,
            "atol": *atol,
            "rtol": *rtol,
            "tensor_results": []interface{}{},
            "missing_in_file1": []string{},
            "missing_in_file2": []string{},
            "error": fmt.Sprintf("file2: %v", err),
        })
        return 1
    }

    res, err := compare.Compare(c1, c2, *mode, *atol, *rtol)
    if err != nil {
        outputJSON(map[string]interface{}{
            "match": false,
            "mode": *mode,
            "atol": *atol,
            "rtol": *rtol,
            "tensor_results": []interface{}{},
            "missing_in_file1": []string{},
            "missing_in_file2": []string{},
            "error": err.Error(),
        })
        return 1
    }

    outputJSON(res)
    if res.Match {
        return 0
    }
    return 1
}

func runValidateManifest(args []string) int {
    if len(args) != 1 {
        outputJSON(map[string]interface{}{"error": "usage: repro-verify validate-manifest <file.toml>"})
        return 1
    }
    res := manifest.Validate(args[0])
    outputJSON(res)
    if res.Valid {
        return 0
    }
    return 1
}

func runAuditLineage(args []string) int {
    if len(args) != 1 {
        outputJSON(map[string]interface{}{"error": "usage: repro-verify audit-lineage <file.json>"})
        return 1
    }
    res := lineage.Audit(args[0])
    outputJSON(res)
    if res.Valid {
        return 0
    }
    return 1
}

func runGenerateReport(args []string) int {
    fs := flag.NewFlagSet("generate-report", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    checkpoint := fs.String("checkpoint", "", "checkpoint file to verify")
    comparePath := fs.String("compare", "", "second checkpoint to compare")
    lineagePath := fs.String("lineage", "", "lineage file to audit")

    pos, err := parseMixedArgs(fs, args)
    if err != nil {
        outputJSON(map[string]interface{}{"error": err.Error()})
        return 1
    }
    if len(pos) != 1 {
        outputJSON(map[string]interface{}{"error": "usage: repro-verify generate-report <manifest.toml> [flags]"})
        return 1
    }

    rep, code := report.Generate(pos[0], *checkpoint, *comparePath, *lineagePath)
    outputJSON(rep)
    return code
}

func runMergeCheckpoints(args []string) int {
    fs := flag.NewFlagSet("merge-checkpoints", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    conflict := fs.String("conflict", "first", "conflict strategy")

    pos, err := parseMixedArgs(fs, args)
    if err != nil {
        outputJSON(map[string]interface{}{"error": err.Error()})
        return 1
    }
    if len(pos) < 3 {
        outputJSON(map[string]interface{}{"error": "usage: repro-verify merge-checkpoints <output> <file1> <file2> ... [flags]"})
        return 1
    }

    res, err := merge.Merge(pos[0], pos[1:], *conflict)
    if err != nil {
        outputJSON(map[string]interface{}{"error": err.Error()})
        return 1
    }
    outputJSON(res)
    return 0
}

func runDriftAnalysis(args []string) int {
    fs := flag.NewFlagSet("drift-analysis", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)

    pos, err := parseMixedArgs(fs, args)
    if err != nil {
        outputJSON(map[string]interface{}{"error": err.Error()})
        return 1
    }
    if len(pos) < 2 {
        outputJSON(map[string]interface{}{"error": "usage: repro-verify drift-analysis <file1> <file2> <file3> ... [flags]"})
        return 1
    }

    res, err := drift.Analyze(pos)
    if err != nil {
        outputJSON(map[string]interface{}{"error": err.Error()})
        return 1
    }
    outputJSON(res)
    return 0
}

func parseMixedArgs(fs *flag.FlagSet, args []string) ([]string, error) {
    var positional []string
    var flagArgs []string

    for i := 0; i < len(args); i++ {
        arg := args[i]
        if arg == "--" {
            positional = append(positional, args[i+1:]...)
            break
        }
        if strings.HasPrefix(arg, "--") {
            if strings.Contains(arg, "=") {
                flagArgs = append(flagArgs, arg)
                continue
            }
            if i+1 >= len(args) {
                return nil, fmt.Errorf("flag %s requires a value", arg)
            }
            flagArgs = append(flagArgs, arg+"="+args[i+1])
            i++
        } else {
            positional = append(positional, arg)
        }
    }

    if err := fs.Parse(flagArgs); err != nil {
        return nil, err
    }
    return positional, nil
}

func outputJSON(v interface{}) {
    enc := json.NewEncoder(os.Stdout)
    enc.SetIndent("", "  ")
    _ = enc.Encode(v)
}
